        pub fn @"members"(@"ir.node": @"ir.Sexp") []const @"ir.Sexp" {
            return @"ir.restAt"(@"ir.node", .@"enum", 3, "ir.Enum.members");
        }
    };
    pub const Errors = struct {
        pub fn @"name"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"errors", 1, "ir.Errors.name");
